## Vanilla JS + HTML

```html
<button id="deleteBtn">Delete Item</button>

<div id="confirmModal" class="modal hidden">
  <div class="modal-content">
    <h2>Confirm Deletion</h2>
    <p>Are you sure? This cannot be undone.</p>
    <button id="confirmDelete" class="btn-danger">Delete</button>
    <button id="cancelDelete" class="btn-secondary">Cancel</button>
  </div>
</div>

<style>
  .modal {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
  }
  .modal.hidden {
    display: none;
  }
  .modal-content {
    background: white;
    padding: 2rem;
    border-radius: 8px;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
  }
  button {
    margin: 0.5rem;
    padding: 0.5rem 1rem;
  }
</style>

<script>
  const deleteBtn = document.getElementById('deleteBtn');
  const modal = document.getElementById('confirmModal');
  const confirmDelete = document.getElementById('confirmDelete');
  const cancelDelete = document.getElementById('cancelDelete');

  deleteBtn.addEventListener('click', () => {
    modal.classList.remove('hidden');
  });

  confirmDelete.addEventListener('click', () => {
    // Perform actual deletion here
    console.log('Item deleted');
    modal.classList.add('hidden');
  });

  cancelDelete.addEventListener('click', () => {
    modal.classList.add('hidden');
  });
</script>
```

## React

```jsx
import { useState } from 'react';

export function ItemList() {
  const [showConfirm, setShowConfirm] = useState(false);

  const handleDelete = () => {
    console.log('Item deleted');
    setShowConfirm(false);
  };

  return (
    <>
      <button onClick={() => setShowConfirm(true)}>Delete Item</button>

      {showConfirm && (
        <div className="modal">
          <div className="modal-content">
            <h2>Confirm Deletion</h2>
            <p>Are you sure? This cannot be undone.</p>
            <button className="btn-danger" onClick={handleDelete}>
              Delete
            </button>
            <button className="btn-secondary" onClick={() => setShowConfirm(false)}>
              Cancel
            </button>
          </div>
        </div>
      )}
    </>
  );
}
```

Modal shown on delete click. Cancel hides it. Confirm triggers deletion logic + closes modal.
